#!/usr/bin/env python3
"""
make.fun bounty entry: coolest-art-01
Title: Celestial Phoenix
Description: A 1024x1024 celestial phoenix over a violet nebula.
"""

import base64
import os

IMAGE_BASE64 = """"""

def main():
    output_dir = "/output"
    os.makedirs(output_dir, exist_ok=True)
    output_path = os.path.join(output_dir, "entry.png")
    
    image_bytes = base64.b64decode(IMAGE_BASE64)
    with open(output_path, "wb") as f:
        f.write(image_bytes)

if __name__ == "__main__":
    main()
